import math


def l2_normalise(vector):
    norm = math.sqrt(sum(value * value for value in vector))
    if norm == 0.0:
        raise ValueError("cannot normalise a zero vector")
    return [value / norm for value in vector]


def cosine(a, b):
    if len(a) != len(b):
        raise ValueError("embeddings must have the same dimension")
    left = l2_normalise(a)
    right = l2_normalise(b)
    return sum(x * y for x, y in zip(left, right))


def verify(a, b, threshold):
    score = cosine(a, b)
    return score, score > threshold


def rates(genuine, impostor, threshold):
    if not genuine or not impostor:
        raise ValueError("both score sets must be non-empty")
    false_accept = sum(1 for score in impostor if score > threshold) / len(impostor)
    false_reject = sum(1 for score in genuine if score <= threshold) / len(genuine)
    return false_accept, false_reject


def equal_error_rate(genuine, impostor):
    candidates = sorted(set(list(genuine) + list(impostor)))
    candidates = [candidates[0] - 1.0] + candidates
    best = None
    for threshold in candidates:
        far, frr = rates(genuine, impostor, threshold)
        gap = abs(far - frr)
        if best is None or gap < best[0]:
            best = (gap, (far + frr) / 2, threshold)
    return best[1], best[2]
